# already covered as one common computation graph in this topic
def export_to_onnx_style(framework_model):
    # already covered as exporting from a training framework in this topic
    onnx_graph = {
        "operators": [],
        "weights": framework_model["weights"],
    }
    for layer in framework_model["layers"]:
        # already covered as converting framework-specific operations into ONNX equivalents in this topic
        onnx_operator = {"type": layer["framework_op"].replace("fw_", "onnx_"), "params": layer["params"]}
        onnx_graph["operators"].append(onnx_operator)
    return onnx_graph

framework_model = {
    "weights": {"w1": 0.5, "w2": -0.3},
    "layers": [
        {"framework_op": "fw_dense", "params": {"units": 8}},
        {"framework_op": "fw_relu", "params": {}},
    ],
}

onnx_model = export_to_onnx_style(framework_model)
print(f"Original framework model (already covered in this topic): {framework_model}")
print(f"\nExported ONNX-style graph (already covered in this topic): {onnx_model}")

# already covered as running inference with an ONNX runtime in this topic
print("\nAny ONNX-compatible runtime could now genuinely load and run this graph, without the original framework")
